#!/usr/bin/env python3
import json
import os
import re
import sys
import time
import urllib.request
from pathlib import Path

DOC_URL = "https://cleanshot.com/docs-api"
CACHE_DAYS = 7

CACHE_DIR = Path(
    os.environ.get(
        "alfred_workflow_cache",
        str(Path.home() / "Library/Caches/com.chatgpt.cleanshotx.actions"),
    )
)

CACHE_FILE = CACHE_DIR / "commands.json"

ACTIONS = ["copy", "save", "annotate", "upload", "pin"]

RUNNABLE_COMMANDS = {
    "all-in-one",
    "capture-area",
    "capture-previous-area",
    "capture-fullscreen",
    "capture-window",
    "self-timer",
    "scrolling-capture",
    "pin",
    "record-screen",
    "capture-text",
    "open-annotate",
    "open-from-clipboard",
    "toggle-desktop-icons",
    "hide-desktop-icons",
    "show-desktop-icons",
    "open-history",
    "restore-recently-closed",
    "open-settings",
}
ACTION_COMMANDS = {
    "capture-area",
    "capture-previous-area",
    "capture-fullscreen",
    "capture-window",
    "self-timer",
}

FALLBACK_COMMANDS = sorted(RUNNABLE_COMMANDS)


def titleize(value):
    return value.replace("-", " ").title()


def load_cache():
    if not CACHE_FILE.exists():
        return None

    age = time.time() - CACHE_FILE.stat().st_mtime
    if age > CACHE_DAYS * 24 * 60 * 60:
        return None

    try:
        data = json.loads(CACHE_FILE.read_text(encoding="utf-8"))
    except Exception:
        return None

    if not isinstance(data, list):
        return None

    commands = sorted({c for c in data if isinstance(c, str)} & RUNNABLE_COMMANDS)
    return commands or None


def save_cache(commands):
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    CACHE_FILE.write_text(
        json.dumps(commands, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )


def fetch_commands():
    req = urllib.request.Request(
        DOC_URL,
        headers={"User-Agent": "Alfred CleanShot X Workflow"},
    )

    with urllib.request.urlopen(req, timeout=8) as response:
        html = response.read().decode("utf-8", errors="ignore")

    found = set(
        re.findall(r"cleanshot://([a-z0-9][a-z0-9-]*)\b", html)
    )

    commands = sorted(found & RUNNABLE_COMMANDS)

    return commands or FALLBACK_COMMANDS


def get_commands():
    cached = load_cache()
    if cached:
        return cached

    try:
        commands = fetch_commands()
        save_cache(commands)
        return commands
    except Exception:
        return FALLBACK_COMMANDS


def make_items(commands, query):
    query_lower = query.lower().strip()
    items = []

    for command in commands:
        base_url = f"cleanshot://{command}"
        title = titleize(command)
        haystack = f"{command} {title}".lower()

        if not query_lower or query_lower in haystack:
            items.append({
                "title": title,
                "subtitle": base_url,
                "arg": base_url,
                "uid": command,
            })

        if command in ACTION_COMMANDS:
            for action in ACTIONS:
                action_url = f"{base_url}?action={action}"
                action_title = f"{title} -> {titleize(action)}"
                action_haystack = f"{command} {title} {action}".lower()

                if not query_lower or query_lower in action_haystack:
                    items.append({
                        "title": action_title,
                        "subtitle": action_url,
                        "arg": action_url,
                        "uid": f"{command}-{action}",
                    })

    if not items:
        items.append({
            "title": "No CleanShot X command found",
            "subtitle": "Try another query",
            "valid": False,
        })

    return items


def main():
    query = " ".join(sys.argv[1:]) if len(sys.argv) > 1 else ""
    commands = get_commands()
    items = make_items(commands, query)

    print(json.dumps({"items": items}, ensure_ascii=False))


if __name__ == "__main__":
    main()
